// Standalone blank form generated by the same module used in the application.
// Node 22+; run from repository root: node scripts/export-team-form.mjs
import { build } from "esbuild";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import path from "node:path";
import { fileURLToPath } from "node:url";
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
await mkdir(path.join(root, ".wrangler", "team-forms"), { recursive: true });
await mkdir(path.join(root, "docs", "forms"), { recursive: true });
const bundle = path.join(root, ".wrangler", "team-forms", "workbook.cjs");
await build({ entryPoints: [path.join(root, "web/src/lib/team-workbook.ts")], outfile: bundle, bundle: true, platform: "node", format: "cjs", external: ["exceljs"] });
const { createTeamWorkbook } = createRequire(import.meta.url)(bundle);
const seed = await readFile(path.join(root, "api/src/db/seed.sql"), "utf8");
const entities = [...seed.matchAll(/\('(?:dir|unit|sec)-[^']+',\s*'((?:[^']|'')*)',\s*'([^']+)',\s*'(?:directorate|unit|secretariat)'/g)]
  .map(match => ({ name: match[1].replaceAll("''", "'"), code: match[2] }));
const bytes = await createTeamWorkbook({ year: 2026, quarter: 3, team: "", members: "", entities });
const destination = path.join(root, "docs/forms/OHCS-Q3-2026-Team-Maintenance-Form.xlsx");
await writeFile(destination, bytes);
console.log(`Created ${destination}. Directory codes come from the local seed; in-app downloads use the current directory.`);
const wordBundle = path.join(root, ".wrangler/team-forms/word.cjs");
await build({ entryPoints: [path.join(root, "web/src/lib/team-word.ts")], outfile: wordBundle, bundle: true, platform: "node", format: "cjs", external: ["docx", "jszip"] });
const { createTeamWord } = createRequire(import.meta.url)(wordBundle);
const wordDestination = path.join(root, "docs/forms/OHCS-Q3-2026-Team-Maintenance-Form.docx");
await writeFile(wordDestination, await createTeamWord({ year: 2026, quarter: 3, team: "", members: "", entities, devicePages: 3 }));
console.log(`Created ${wordDestination}.`);
